#!/usr/bin/env node
/**
 * Stages the runtime data the game reads from SilentDepth_Assets into the UE
 * project, and records the source hash of every file.
 *
 * Authority direction (DATA-002): SilentDepth_Assets is the only source of
 * truth. Everything under Config/SilentDepth is generated by this script and
 * hashed into _sync_manifest.json, so a copy that drifts fails the check
 * instead of silently disagreeing with production data. The loader never reads
 * the asset library itself: a packaged build has no repo next to it.
 *
 *   node tools/ue4/sync-tech-tree-data.mjs           # copy + write manifest
 *   node tools/ue4/sync-tech-tree-data.mjs --check   # fail on any drift
 */
import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..', '..');
const assetRoot = path.join(repoRoot, 'SilentDepth_Assets');
const configRoot = path.join(repoRoot, 'ue4', 'SilentDepthUE', 'Config', 'SilentDepth');
const manifestPath = path.join(configRoot, '_sync_manifest.json');
const manifestSchema = 'silent-depth-runtime-data-sync-v1';

/**
 * path: destination relative to Config/SilentDepth.
 * source: file inside SilentDepth_Assets.
 */
const sources = [
  // Tech-tree catalogues and their tier/branch documents.
  { path: 'TechTree/submarine_catalogue.json', source: 'Manifest/submarine_manifest.json' },
  { path: 'TechTree/submarine_tree.json', source: 'TechnologyTree/tier_manifest.json' },
  { path: 'TechTree/weapon_catalogue.json', source: 'Weapons/Manifest/weapon_manifest.json' },
  {
    path: 'TechTree/weapon_tree.json',
    source: 'Weapons/TechnologyTree/weapon_technology_tree.json',
  },
  { path: 'TechTree/sensor_catalogue.json', source: 'Sensors/Manifest/sensor_manifest.json' },
  {
    path: 'TechTree/sensor_tree.json',
    source: 'Sensors/TechnologyTree/sensor_technology_tree.json',
  },
  {
    path: 'TechTree/defensive_catalogue.json',
    source: 'DefensiveSystems/Manifest/defensive_system_manifest.json',
  },
  {
    path: 'TechTree/defensive_tree.json',
    source: 'DefensiveSystems/TechnologyTree/defensive_technology_tree.json',
  },
  {
    path: 'TechTree/propulsion_catalogue.json',
    source: 'Propulsion/Manifest/propulsion_manifest.json',
  },
  {
    path: 'TechTree/propulsion_tree.json',
    source: 'Propulsion/TechnologyTree/propulsion_technology_tree.json',
  },
  // Compatibility matrices and slot definitions (TECH-005).
  {
    path: 'TechTree/weapon_compatibility.json',
    source: 'Weapons/Manifest/weapon_submarine_compatibility.json',
  },
  { path: 'TechTree/weapon_slots.json', source: 'Weapons/Manifest/loadout_manifest.json' },
  {
    path: 'TechTree/sensor_compatibility.json',
    source: 'Sensors/Manifest/submarine_sensor_compatibility.json',
  },
  {
    path: 'TechTree/defensive_compatibility.json',
    source: 'DefensiveSystems/Manifest/submarine_defensive_compatibility.json',
  },
  {
    path: 'TechTree/defensive_slots.json',
    source: 'DefensiveSystems/Manifest/defensive_loadout_manifest.json',
  },
  {
    path: 'TechTree/propulsion_compatibility.json',
    source: 'Propulsion/Manifest/submarine_propulsion_compatibility.json',
  },
  // Blender assembly documents (SOCKET-001): the logical mount points, the
  // anchor they come from and their transforms. Read at load time by
  // TechTreeSocketLoaders.cpp; a hull with none is simply absent here.
  {
    path: 'TechTree/Sockets/RU_SSN_Yasen_ASSEMBLY.json',
    source: 'Submarines/SSN/Russia/Yasen/Documentation/RU_SSN_Yasen_ASSEMBLY.json',
  },
  // SOCKET-001: the Akula equipment anchors live on a working copy of the
  // master (DEC-002); the master itself is never modified.
  {
    path: 'TechTree/Sockets/RU_SSN_Akula_ASSEMBLY.json',
    source: 'Submarines/SSN/Russia/Akula/Documentation/RU_SSN_Akula_ASSEMBLY.json',
  },
  // Copies that predate the TechTree directory. They are still staged so that
  // nothing under Config/SilentDepth escapes the drift check.
  { path: 'submarine_manifest.json', source: 'Manifest/submarine_manifest.json' },
  { path: 'technology_tree.json', source: 'TechnologyTree/technology_tree.json' },
  { path: 'tier_manifest.json', source: 'TechnologyTree/tier_manifest.json' },
];

const sha256 = (buffer) => createHash('sha256').update(buffer).digest('hex').toLowerCase();

async function readSource(entry) {
  const sourcePath = path.join(assetRoot, entry.source);
  try {
    return await readFile(sourcePath);
  } catch (error) {
    throw new Error(
      `missing source asset-library document: ${entry.source} (${error.code ?? error.message})`,
      { cause: error },
    );
  }
}

async function run() {
  const checkOnly = process.argv.includes('--check');
  const files = [];
  const drifted = [];

  for (const entry of sources) {
    const bytes = await readSource(entry);
    const digest = sha256(bytes);
    files.push({ path: entry.path, source: entry.source, sha256: digest });

    const destPath = path.join(configRoot, entry.path);
    if (checkOnly) {
      let staged;
      try {
        staged = await readFile(destPath);
      } catch {
        drifted.push(`${entry.path}: missing from Config/SilentDepth`);
        continue;
      }
      if (sha256(staged) !== digest) {
        drifted.push(`${entry.path}: staged copy differs from ${entry.source}`);
      }
      continue;
    }
    await mkdir(path.dirname(destPath), { recursive: true });
    await writeFile(destPath, bytes);
  }

  const manifest =
    JSON.stringify(
      {
        schema: manifestSchema,
        note: '生成物。唯一权威是 SilentDepth_Assets；本文件记录每个运行时副本的来源与哈希。请勿手工编辑。',
        files,
      },
      null,
      2,
    ) + '\n';

  if (checkOnly) {
    let existing = null;
    try {
      existing = await readFile(manifestPath, 'utf8');
    } catch {
      drifted.push('_sync_manifest.json: missing');
    }
    if (existing !== null && existing !== manifest) {
      drifted.push('_sync_manifest.json: manifest does not match the asset library');
    }
    if (drifted.length > 0) {
      console.error('runtime data has drifted from the asset library:');
      for (const item of drifted) {
        console.error(`  - ${item}`);
      }
      console.error('run: node tools/ue4/sync-tech-tree-data.mjs');
      process.exitCode = 1;
      return;
    }
    console.log(`runtime data is in sync (${files.length} files)`);
    return;
  }

  await writeFile(manifestPath, manifest);
  console.log(
    `staged ${files.length} runtime documents into ${path.relative(repoRoot, configRoot)}`,
  );
}

run().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
